var t=`0642-mullah-robe`;var i=`world-0642`;var a=`SD`;var o=`northern-africa`;var s=4;var l=77;var r={en:`Mullah Robe`,ua:`Мулла робе`};var g={en:`Mullah Robe is a Sudan classic prepared with lamb, yellow onion, okra, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Мулла робе, страва кухні країни Судан зі складниками: ягнятина, жовта цибуля, бамія, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 10 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 10 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:10,i:[[`lamb`,540,`g`],[`red-palm-oil`,50,`ml`],[`yellow-onion`,180,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 55 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 55 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:55,i:[[`okra`,300,`g`],[`tomato`,280,`g`],[`water`,800,`ml`],[`ground-cumin`,5,`g`],[`table-salt`,null,`to_taste`]]},{en:`Whisk yogurt and garlic until smooth, then serve the cool sauce alongside the fully cooked okra-and-lamb stew.`,ua:`Змішайте йогурт із часником до однорідності й подавайте прохолодний соус окремо від готового рагу з бамії та баранини.`,t:[`sauteing`,`reducing-sauce`],m:8,i:[[`plain-yogurt`,230,`g`],[`garlic`,3,`clove`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`cilantro`,20,`g`]]}];var d={slug:t,id:i,country:`SD`,region:o,servings:4,minutes:77,title:r,text:g,steps:u};export{a as country,d as default,i as id,l as minutes,o as region,s as servings,t as slug,u as steps,g as text,r as title};